Below is a **self‑contained C# console program** that demonstrates how to create a custom attribute, apply it to a class, method, property and field, and then read those attributes at runtime using reflection.

```csharp
using System;
using System.Reflection;

// -----------------------------------------------------------------
// 1. Define a custom attribute
// -----------------------------------------------------------------
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method |
                AttributeTargets.Property | AttributeTargets.Field,
                Inherited = false, AllowMultiple = true)]
public sealed class MyInfoAttribute : Attribute
{
    // Positional argument
    public string Note { get; }

    // Optional named arguments
    public int Version { get; set; } = 1;
    public bool IsActive { get; set; } = true;

    public MyInfoAttribute(string note) => Note = note;
}

// -----------------------------------------------------------------
// 2. Apply the attribute to various program elements
// -----------------------------------------------------------------
[MyInfo("This class demonstrates attribute usage", Version = 2, IsActive = false)]
public class DemoClass
{
    [MyInfo("Important field", Version = 1)]
    private int importantField = 42;

    [MyInfo("Readonly property")]
    public string ReadOnlyProp => "ReadOnly";

    [MyInfo("Mutable property", IsActive = false)]
    public int MutableProp { get; set; } = 7;

    [MyInfo("Demo method", Version = 3)]
    public void DemoMethod()
    {
        Console.WriteLine("DemoMethod invoked");
    }
}

// -----------------------------------------------------------------
// 3. Use reflection to discover and print attribute data
// -----------------------------------------------------------------
class Program
{
    static void Main()
    {
        Type demoType = typeof(DemoClass);

        Console.WriteLine($"--- Attributes on class {demoType.Name} ---");
        PrintAttributes(demoType.GetCustomAttributes());

        Console.WriteLine();

        // Field attributes
        foreach (FieldInfo field in demoType.GetFields(BindingFlags.NonPublic | BindingFlags.Instance))
        {
            Console.WriteLine($"--- Attributes on field {field.Name} ---");
            PrintAttributes(field.GetCustomAttributes());
        }

        Console.WriteLine();

        // Property attributes
        foreach (PropertyInfo prop in demoType.GetProperties(BindingFlags.Public | BindingFlags.Instance))
        {
            Console.WriteLine($"--- Attributes on property {prop.Name} ---");
            PrintAttributes(prop.GetCustomAttributes());
        }

        Console.WriteLine();

        // Method attributes
        foreach (MethodInfo method in demoType.GetMethods(BindingFlags.Public | BindingFlags.Instance))
        {
            // Skip the automatically generated property accessors
            if (method.IsSpecialName) continue;

            Console.WriteLine($"--- Attributes on method {method.Name} ---");
            PrintAttributes(method.GetCustomAttributes());
        }

        Console.WriteLine("\n--- Using attribute data to drive logic ---");
        var demo = new DemoClass();

        // Example: only call methods that have MyInfoAttribute.IsActive == true
        foreach (MethodInfo method in demoType.GetMethods(BindingFlags.Public | BindingFlags.Instance))
        {
            if (method.IsSpecialName) continue;  // skip property accessors

            var attrs = method.GetCustomAttributes<MyInfoAttribute>(false);
            foreach (var attr in attrs)
            {
                if (attr.IsActive) // decide whether to invoke
                {
                    Console.WriteLine($"Invoking {method.Name} because IsActive = true");
                    method.Invoke(demo, null);
                }
                else
                {
                    Console.WriteLine($"Skipping {method.Name} because IsActive = false");
                }
            }
        }
    }

    // Helper that prints all MyInfoAttribute instances
    static void PrintAttributes(IEnumerable<Attribute> attributes)
    {
        foreach (var attr in attributes)
        {
            if (attr is MyInfoAttribute myAttr)
            {
                Console.WriteLine($"  Note    : {myAttr.Note}");
                Console.WriteLine($"  Version : {myAttr.Version}");
                Console.WriteLine($"  Active  : {myAttr.IsActive}");
            }
        }
    }
}
```

### What the program shows

1. **Attribute definition**  
   `MyInfoAttribute` is marked with `[AttributeUsage]` to limit its targets and allow multiple instances. It has a positional constructor argument (`Note`) and optional named properties (`Version`, `IsActive`).

2. **Applying attributes**  
   The attribute is applied to a class, a private field, two properties, and a method. Each instance can supply different values for the optional named properties.

3. **Reflection**  
   * `GetCustomAttributes()` retrieves all attributes applied to a member.  
   * We loop through class members (`FieldInfo`, `PropertyInfo`, `MethodInfo`) and print the values stored in each `MyInfoAttribute`.  
   * A small example shows how you can use attribute data at runtime (e.g., only invoke methods marked as active).

Compile and run the program to see the console output that lists all attribute data and demonstrates dynamic behavior based on that metadata.
